create or replace function public.owner_dashboard_summary() returns table (total_garages bigint, total_clients bigint, total_vehicules bigint, ca_total_mois bigint, ca_total_annee bigint, top_garage_nom text, top_garage_ca bigint) language plpgsql stable security definer set search_path = public as $$ declare v_user uuid := auth.uid(); begin if v_user is null then raise exception 'Auth requise'; end if; select count(distinct garage_id), count(distinct c.id), count(distinct v.id), coalesce(sum(i.total), 0)::bigint, coalesce(sum(i2.total), 0)::bigint into total_garages, total_clients, total_vehicules, ca_total_mois, ca_total_annee from garage_users gu left join customers c on c.garage_id = gu.garage_id and gu.role in ('proprietaire','gerant') left join vehicles v on v.garage_id = gu.garage_id left join invoices i on i.garage_id = gu.garage_id and i.date_emission >= date_trunc('month', now()) and i.statut not in ('brouillon','annulee') left join invoices i2 on i2.garage_id = gu.garage_id and i2.date_emission >= date_trunc('year', now()) and i2.statut not in ('brouillon','annulee') where gu.user_id = v_user and gu.actif = true; with garage_ca as (select g.nom, sum(i.total)::bigint as ca from garage_users gu join garages g on g.id = gu.garage_id join invoices i on i.garage_id = g.id and i.date_emission >= date_trunc('month', now()) and i.statut not in ('brouillon','annulee') where gu.user_id = v_user and gu.actif = true group by g.id, g.nom order by ca desc limit 1) select nom, ca into top_garage_nom, top_garage_ca from garage_ca; return next; end $$;
create or replace function public.get_my_garages() returns table (id uuid, nom text, slug text, role user_role, actif boolean, ca_mois bigint, clients_count bigint, or_en_cours bigint) language plpgsql stable security definer set search_path = public as $$ begin return query select g.id, g.nom, g.slug, gu.role, gu.actif, (select coalesce(sum(i.total),0)::bigint from invoices i where i.garage_id = g.id and i.date_emission >= date_trunc('month', now()) and i.statut not in ('brouillon','annulee')) as ca_mois, (select count(*) from customers c where c.garage_id = g.id) as clients_count, (select count(*) from work_orders w where w.garage_id = g.id and w.statut not in ('termine','livre')) as or_en_cours from garage_users gu join garages g on g.id = gu.garage_id where gu.user_id = auth.uid() and gu.actif = true order by ca_mois desc nulls last; end $$;
grant execute on function public.owner_dashboard_summary() to authenticated; grant execute on function public.get_my_garages() to authenticated;
